begin;
select set_config('biome.ticket_a',gen_random_uuid()::text,true),set_config('biome.ticket_b',gen_random_uuid()::text,true),set_config('biome.ticket_hash',replace(gen_random_uuid()::text,'-','')||replace(gen_random_uuid()::text,'-',''),true);
insert into auth.users(id)values(current_setting('biome.ticket_a')::uuid),(current_setting('biome.ticket_b')::uuid);
insert into public.biome_profiles(id,username)values(current_setting('biome.ticket_a')::uuid,'TicketA_'||left(current_setting('biome.ticket_a'),8)),(current_setting('biome.ticket_b')::uuid,'TicketB_'||left(current_setting('biome.ticket_b'),8));
set local role authenticated;
select set_config('request.jwt.claim.sub',current_setting('biome.ticket_a'),true);
select public.biome_create_server_ticket(current_setting('biome.ticket_hash'),repeat('AA:',31)||'AA');
reset role;
do $$begin if not exists(select 1 from public.biome_server_tickets where ticket_hash=current_setting('biome.ticket_hash') and player_id=current_setting('biome.ticket_a')::uuid)then raise exception 'Ticket was not bound to its issuer';end if;end;$$;
set local role anon;
select set_config('request.jwt.claim.sub','',true);
do $$begin
 if has_table_privilege('anon','public.biome_server_tickets','SELECT') or has_table_privilege('authenticated','public.biome_server_tickets','SELECT') then raise exception 'Private ticket table can be read';end if;
 if has_table_privilege('anon','public.biome_server_tickets','INSERT') or has_table_privilege('authenticated','public.biome_server_tickets','INSERT') then raise exception 'Private ticket table can be written directly';end if;
 if has_function_privilege('anon','public.biome_create_server_ticket(text,text)','EXECUTE') then raise exception 'Anonymous ticket issuance is enabled';end if;
 if exists(select 1 from public.biome_redeem_server_ticket(current_setting('biome.ticket_hash'),repeat('BB:',31)||'BB'))then raise exception 'Wrong destination fingerprint accepted';end if;
 if not exists(select 1 from public.biome_redeem_server_ticket(current_setting('biome.ticket_hash'),repeat('AA:',31)||'AA') where id=current_setting('biome.ticket_a')::uuid and username='TicketA_'||left(current_setting('biome.ticket_a'),8)) then raise exception 'Valid one-use ticket failed';end if;
 if exists(select 1 from public.biome_redeem_server_ticket(current_setting('biome.ticket_hash'),repeat('AA:',31)||'AA'))then raise exception 'Ticket replay succeeded';end if;
end;$$;
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub',current_setting('biome.ticket_b'),true);
select public.biome_create_server_ticket(current_setting('biome.ticket_hash'),repeat('AA:',31)||'AA');
reset role;
do $$begin if not exists(select 1 from public.biome_server_tickets where ticket_hash=current_setting('biome.ticket_hash') and player_id=current_setting('biome.ticket_b')::uuid) then raise exception 'Ticket identity can be supplied by another user';end if;end;$$;
update public.biome_server_tickets set expires_at=now()-interval '1 second' where ticket_hash=current_setting('biome.ticket_hash');
set local role anon;
select set_config('request.jwt.claim.sub','',true);
do $$begin if exists(select 1 from public.biome_redeem_server_ticket(current_setting('biome.ticket_hash'),repeat('AA:',31)||'AA')) then raise exception 'Expired ticket accepted';end if;end;$$;
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub',current_setting('biome.ticket_a'),true);
do $$declare rejected boolean:=false;begin
 for i in 1..10 loop perform public.biome_create_server_ticket(md5(current_setting('biome.ticket_a')||i::text)||md5(i::text||current_setting('biome.ticket_a')),repeat('AA:',31)||'AA');end loop;
 begin perform public.biome_create_server_ticket(repeat('f',64),repeat('AA:',31)||'AA');exception when raise_exception then rejected:=sqlerrm like 'Wait a minute%';end;
 if not rejected then raise exception 'Outstanding ticket bound not enforced';end if;
end;$$;
rollback;
select 'PASS: private table, issuer binding, wrong-server denial, valid redemption, replay denial, expiry and ticket bound. All fixtures rolled back.' as result;
